import {uiNode,statusBadge} from './application.mjs';
import {componentRepository} from './component-repository.mjs';
import {assemblyRepository} from './assembly-repository.mjs';
import {currentAdminOrderRepository} from '../backend/order-data.mjs?v=external-v1';
import {currentOperationsRepository} from '../backend/operations-admin.mjs';
import {createCMSRepository} from './hub-cms/repository.mjs';
import {articleState} from './hub-cms/library.mjs';
import {effectiveStore,activeAnnouncement,ukDate} from '../operations/model.mjs';

export const overviewSources={
 inventory:()=>componentRepository().list(),catalogue:()=>assemblyRepository().list(),orders:()=>currentAdminOrderRepository().list(),
 website:async()=>{const repo=currentOperationsRepository();const [store,posts]=await Promise.all([repo.store(),repo.posts()]);return {store,posts};},
 articles:()=>createCMSRepository().list()
};
export function overviewSummary(id,data,now=Date.now()){
 if(id==='inventory'){const active=data.filter(x=>x.active),empty=active.filter(x=>x.stock<=0);return {lines:[`${active.length} active · ${data.length} total components`,`${empty.length} active components out of stock`],attention:empty.length?`${empty.length} active components are out of stock.`:null,detail:empty.slice(0,5).map(x=>x.name).join(' · '),healthy:'No active components are out of stock.'};}
 if(id==='catalogue')return {lines:[`${data.filter(x=>x.active&&x.kind!=='wiring-kit').length} active product assemblies`,`${data.filter(x=>x.active&&x.kind==='wiring-kit').length} active wiring kit definitions`],healthy:data.length?'Shared catalogue available.':'No shared assemblies or kit definitions yet.'};
 if(id==='orders'){const paid=data.filter(x=>['paid','partially_refunded'].includes(x.paymentStatus)&&!(x.paymentStatus==='partially_refunded'&&!x.partialRefundAcknowledged)),queued=paid.filter(x=>x.fulfilmentStatus==='paid').length,production=paid.filter(x=>x.fulfilmentStatus==='in_production').length,dispatch=paid.filter(x=>x.fulfilmentStatus==='ready_to_dispatch').length,reviews=data.filter(x=>x.paymentStatus==='partially_refunded'&&!x.partialRefundAcknowledged).length;return {lines:[`${queued} awaiting production`,`${production} in production`,`${dispatch} ready to dispatch`,`${reviews} refund reviews awaiting acknowledgement`],attention:queued+dispatch+reviews?`${queued+dispatch+reviews} orders require an operational action.`:null,healthy:'No orders awaiting an operational action.'};}
 if(id==='articles'){const counts=new Map();for(const x of data){const state=articleState(x);counts.set(state,(counts.get(state)||0)+1);}return {lines:['Never published','Draft changes pending','Published'].map(x=>`${counts.get(x)||0} · ${x}`),healthy:data.length?'Article revision state available.':'No articles in the library yet.'};}
 if(id==='website'){const state=effectiveStore(data.store,now),announcement=activeAnnouncement(data.store,data.posts,now),lines=[state.state==='OPEN'?'Store open':'Orders paused'];if(data.store.desired_state==='ORDERS_PAUSED'&&Date.parse(data.store.pause_from)>now)lines.push('Scheduled pause: '+ukDate(data.store.pause_from));if(data.store.resume_at&&Date.parse(data.store.resume_at)>now)lines.push('Scheduled resume: '+ukDate(data.store.resume_at));lines.push(announcement?'Active announcement: '+(announcement.title||'Store update'):'No active announcement');for(const status of ['DRAFT','SCHEDULED','PUBLISHED','ARCHIVED'])lines.push(`${data.posts.filter(x=>x.status===status).length} News records · ${status.toLowerCase()}`);return {lines,attention:state.state==='ORDERS_PAUSED'?'New checkout is paused; existing orders continue.':null,healthy:'Store operating normally.'};}
 throw Error('Unsupported Overview area.');
}
const areas=[['orders','Orders','/admin/orders/'],['inventory','Inventory','/admin/?view=inventory'],['website','Website & News','/admin/site-operations/'],['catalogue','Catalogue','/admin/?view=assemblies'],['articles','Luthier Hub','/admin/hub-cms/']];
// These are workload counts from the same authorised responses, never revenue estimates.
export function overviewMetric(id,data,now=Date.now()){
 if(id==='orders'){const actionable=data.filter(x=>x.paymentStatus==='partially_refunded'&&!x.partialRefundAcknowledged||['paid','partially_refunded'].includes(x.paymentStatus)&&['paid','ready_to_dispatch'].includes(x.fulfilmentStatus));return {value:String(actionable.length),detail:'Production, dispatch or refund review'};}
 if(id==='inventory'){const active=data.filter(x=>x.active);return {value:String(active.filter(x=>x.stock<=0).length),detail:active.length+' active component records'};}
 if(id==='catalogue')return {value:String(data.filter(x=>x.active).length),detail:'Active assemblies and kit definitions'};
 if(id==='website')return {value:effectiveStore(data.store,now).state==='OPEN'?'Open':'Paused',detail:'Current ordering availability'};
 throw Error('Unsupported Overview metric.');
}
export async function bootOverview({document:d=globalThis.document,sources=overviewSources,now=()=>Date.now()}={}){
 const root=d.getElementById('overview-content'),status=d.getElementById('overview-status');if(!root||root.dataset.overviewBound)return;root.dataset.overviewBound='true';status.textContent='Loading current operational state…';root.replaceChildren();
 const metrics=uiNode(d,'section',undefined,'admin-overview-kpis');metrics.setAttribute('aria-label','Current workload');const metricNodes=new Map();
 for(const [id,label,href] of [['orders','Orders to action','/admin/orders/'],['inventory','Out of stock','/admin/?view=inventory'],['catalogue','Active products','/admin/?view=assemblies'],['website','Store status','/admin/site-operations/']]){const card=uiNode(d,'a',undefined,'admin-kpi');card.href=href;card.dataset.metric=id;const value=uiNode(d,'strong','Checking…'),detail=uiNode(d,'small','Authorised records');card.append(uiNode(d,'span',label),value,detail);metrics.append(card);metricNodes.set(id,{card,value,detail});}root.append(metrics);
 const workflow=uiNode(d,'div',undefined,'admin-overview-workflow');root.append(workflow);
 const attention=uiNode(d,'section',undefined,'admin-overview-attention'),heading=uiNode(d,'h2','Needs attention'),items=uiNode(d,'div');items.setAttribute('aria-live','polite');attention.append(heading,items);workflow.append(attention);
 const quick=uiNode(d,'nav',undefined,'admin-overview-actions');quick.setAttribute('aria-label','Overview quick actions');quick.append(uiNode(d,'h2','Quick actions'));for(const [label,href] of [['Open Orders','/admin/orders/'],['Add Component','/admin/?view=inventory&new=component'],['Record marketplace sale','/admin/orders/?new=external'],['Open Conjure','/admin/conjure/'],['Open Luthier Hub','/admin/hub-cms/']]){const a=uiNode(d,'a',label,'admin-quick-link');a.href=href;quick.append(a);}workflow.append(quick);
 const sections=uiNode(d,'div',undefined,'admin-overview-sections');root.append(sections);const states=new Map();
 const paintAttention=()=>{items.replaceChildren();for(const [id,title,href] of areas){const s=states.get(id);if(s?.attention||s?.error){const a=uiNode(d,'a',s.error?title+': status unavailable. Retry below.':s.attention,'admin-attention-item');a.href=href;items.append(a);}}if(!items.childElementCount)items.append(uiNode(d,'p',states.size===areas.length?'No attention items reported by the available data.':'Checking operational state…'));};
 const loads=areas.map(([id,title,href])=>{const section=uiNode(d,'section',undefined,'admin-overview-area');section.dataset.overviewArea=id;const h=uiNode(d,'h2',title),body=uiNode(d,'div'),link=uiNode(d,'a','Open '+title+' →');link.href=href;section.append(h,body,link);sections.append(section);let busy=false;
  const load=async()=>{if(busy)return;busy=true;body.replaceChildren(uiNode(d,'p','Loading…'));section.setAttribute('aria-busy','true');try{const data=await sources[id](),at=now(),summary=overviewSummary(id,data,at);states.set(id,summary);const metric=metricNodes.get(id);if(metric){const result=overviewMetric(id,data,at);metric.value.textContent=result.value;metric.detail.textContent=result.detail;metric.card.dataset.state=summary.attention?'attention':'current';}body.replaceChildren();body.append(statusBadge(d,summary.attention?'Attention':'Current',summary.attention?'warning':'neutral'));if(summary.attention)body.append(uiNode(d,'p',summary.attention,'admin-overview-emphasis'));const list=uiNode(d,'ul',undefined,'admin-status-list');for(const text of summary.lines)list.append(uiNode(d,'li',text));body.append(list);if(summary.detail)body.append(uiNode(d,'p',summary.detail,'admin-overview-detail'));if(!summary.attention)body.append(uiNode(d,'p',summary.healthy,'admin-overview-detail'));}catch{states.set(id,{error:true});const metric=metricNodes.get(id);if(metric){metric.value.textContent='Unavailable';metric.detail.textContent='No value assumed';metric.card.dataset.state='unavailable';}body.replaceChildren(uiNode(d,'p','Status unavailable. No values have been assumed.','admin-feedback'));const retry=uiNode(d,'button','Retry '+title);retry.type='button';retry.addEventListener('click',load);body.append(retry);}finally{busy=false;section.setAttribute('aria-busy','false');paintAttention();}};return load();});
 await Promise.all(loads);status.textContent='Current authorised records. Refresh to check for newer changes.';
}
if(globalThis.document?.getElementById('overview-content'))bootOverview();
